function generateServiceFile(templatePath, template) {
  const fullPath = path.join(PROXY_DIR, templatePath);
  const dir = path.dirname(fullPath);
  
  // Create directory if it doesn't exist
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  
  // Check if file already exists
  if (fs.existsSync(fullPath)) {
    return; // Skip if already exists
  }
  
  let code = template.imports + '\n\n';
  code += `@Injectable({\n`;
  code += `  providedIn: 'root',\n`;
  code += `})\n`;
  code += `export class ${template.className} {\n`;
  code += `  apiName = '${template.apiName}';\n\n`;
  
  if (template.apiName === 'Default') {
    code += `  constructor(private restService: RestService) {}\n\n`;
  } else {
    code += `  constructor(private rest: RestService) {}\n\n`;
  }
  
  template.methods.forEach(method => {
    const paramList = (method.params || []).join(', ');
    const hasConfig = method.hasConfig || false;
    const restVar = template.apiName === 'Default' ? 'restService' : 'rest';
    
    // Check if URL contains template variables (e.g., ${id})
    const urlHasTemplate = method.url && method.url.includes('${');
    const urlQuote = urlHasTemplate ? '`' : `'`;
    
    code += `  ${method.name} = (${paramList}) =>\n`;
    code += `    this.${restVar}.request<any, ${method.returnType}>(\n`;
    code += `      {\n`;
    code += `        method: '${method.method}',\n`;
    code += `        url: ${urlQuote}${method.url}${urlQuote},\n`;
    
    if (method.queryParams) {
      code += `        params: { ${method.queryParams} },\n`;
    }
    
    if (method.body) {
      code += `        body: ${method.body},\n`;
    }
    
    code += `      },\n`;
    
    if (hasConfig) {
      code += `      { apiName: this.apiName, ...config }\n`;
    } else {
      code += `      { apiName: this.apiName }\n`;
    }
    
    code += `    );\n\n`;
  });
  
  code += '}\n';
  
  fs.writeFileSync(fullPath, code, 'utf8');
  console.log(`✅ Created: ${path.relative(PROXY_DIR, fullPath)}`);
}

function generateIndexFiles() {
  // Generate index.ts for identity
  const identityIndexPath = path.join(PROXY_DIR, 'volo/abp/identity/index.ts');
  if (!fs.existsSync(identityIndexPath)) {
    const identityIndexContent = `export * from '../../../identity/models';
export * from './identity-role.service';
export * from './identity-user.service';
`;
    fs.writeFileSync(identityIndexPath, identityIndexContent, 'utf8');
    console.log(`✅ Created: ${path.relative(PROXY_DIR, identityIndexPath)}`);
  }
  
  // Generate index.ts for permission-management
  const permissionIndexPath = path.join(PROXY_DIR, 'volo/abp/permission-management/index.ts');
  if (!fs.existsSync(permissionIndexPath)) {
    const permissionIndexContent = `export * from './permission.service';
export * from '../../../permissionManagement/models';
`;
    fs.writeFileSync(permissionIndexPath, permissionIndexContent, 'utf8');
    console.log(`✅ Created: ${path.relative(PROXY_DIR, permissionIndexPath)}`);
  }
  
  // Generate navigation models and index
  const navigationDir = path.join(PROXY_DIR, 'volo/abp/ui/navigation');
  if (!fs.existsSync(navigationDir)) {
    fs.mkdirSync(navigationDir, { recursive: true });
  }
  
  const navigationModelsPath = path.join(navigationDir, 'models.ts');
  if (!fs.existsSync(navigationModelsPath)) {
    const navigationModelsContent = `export interface ApplicationMenu {
  name: string;
  items: ApplicationMenuItem[];
}

export interface ApplicationMenuItem {
  name: string;
  displayName: string;
  url?: string;
  icon?: string;
  order: number;
  requiredPermissionName?: string;
  items?: ApplicationMenuItem[];
}
`;
    fs.writeFileSync(navigationModelsPath, navigationModelsContent, 'utf8');
    console.log(`✅ Created: ${path.relative(PROXY_DIR, navigationModelsPath)}`);
  }
  
  const navigationIndexPath = path.join(navigationDir, 'index.ts');
  if (!fs.existsSync(navigationIndexPath)) {
    const navigationIndexContent = `export * from './models';
`;
    fs.writeFileSync(navigationIndexPath, navigationIndexContent, 'utf8');
    console.log(`✅ Created: ${path.relative(PROXY_DIR, navigationIndexPath)}`);
  }
}

